private void AddCoreTasksAsync(List<NodeAndParam> taskAndParams, CancellationToken token)
{
    foreach (var task in taskAndParams)
    {
        var generic = new MFAAvalonia.Services.GenericScriptPlayback();
        MFATask? queued = null;
        queued = CreateMaaFWTask(task.Name,
            async () =>
            {
                token.ThrowIfCancellationRequested();
                var inputOnly = task.Entry == MFAAvalonia.Services.GenericScriptPlayback.Entry;
                var wasInputOnly = _inputOnlyPlayback;
                await SetInputOnlyPlaybackAsync(inputOnly, token);
                if (inputOnly)
                {
                    queued!.ContinueOnError = false;
                    return await generic.RunAsync(this, task.SourceItem?.InterfaceItem?.Name ?? task.Name!, token);
                }
                if (wasInputOnly) await HandleDeviceConnectionAsync(token);
                return await MFAAvalonia.Services.ScriptTaskExecution.RunAsync(
                    this, task.SourceItem?.InterfaceItem?.Name ?? task.Name, task.Entry, task.Param,
                    (entry, parameters, cancellation) => TryRunTasksAsync(MaaTasker, entry, parameters, cancellation),
                    () => queued!.ContinueOnError = false, token);
            }, task.Count ?? 1, task.SourceItem, task.RunId);
        TaskQueue.Enqueue(queued);
    }
}
